"4 цифры в частном: 650 318 : 527 = 1 234; 456 192 : 132 = 3 456": "商是 4 位数：650 318 : 527 = 1 234；456 192 : 132 = 3 456",
"Чтобы найти производительность, надо время разделить на работу.": "要求工作效率，得用时间除以工作量。",
"Если 90 + 80 = 170 (км/ч), то за 5 ч они вместе пройдут 850 км.": "如果 90 + 80 = 170（千米/时），那么 5 小时他们一共走 850 千米。",
