"При движении навстречу скорость сближения равна сумме скоростей.": "相向运动时，相遇速度等于速度之和。",
"Через 3 ч при скорости удаления 90 км/ч расстояние равно 270 км.": "3 小时后，相背速度是 90 千米/时，距离等于 270 千米。",
"произведение из 6 цифр: 450 · 600 = 270 000; 4 200 · 70 = 294 000": "积是 6 位数：450 · 600 = 270 000；4 200 · 70 = 294 000",
"произведение из 6 цифр: 450 · 600 = 270 000; 4 200 · 70 = 294 000": "积是 6 位数：450 · 600 = 270 000；4 200 · 70 = 294 000",
