"Как найти производительность v, если известны работа A и время t?": "已知工作量 A 和时间 t，怎样求工作效率 v？",
"Чем задача по двум разностям отличается от задачи по двум суммам?": "由两个差求未知数的题和由两个和求未知数的题有什么不同？",
"v сбл. = v₁ + x, а расстояние S = v сбл. · t. (98 + x) · 2 = 396.": "v相遇 = v₁ + x，而距离 S = v相遇 · t。(98 + x) · 2 = 396。",
"78 ближе к 80. Подобранную цифру потом проверяем умножением на 78.": "78 更接近 80。选出的数字后面还要用乘以 78 来检验。",
"Частное равно 52, делитель — 305, остатка нет. Чему равно делимое?": "商等于 52，除数是 305，没有余数。被除数等于多少？",
"За 4 часа сделали 36 деталей, значит, производительность 9 дет./ч.": "4 小时做了 36 个零件，所以工作效率是 9 个/时。",
"Уравнение 72 + x · 3 = 420 означает то же, что (72 + x) · 3 = 420.": "方程 72 + x · 3 = 420 与 (72 + x) · 3 = 420 的意思相同。",
"2 · 3 = 6, а 24 : 6 = 4. Если скобки не поставить, 24 : 2 · 3 = 36.": "2 · 3 = 6，而 24 : 6 = 4。如果不加括号，24 : 2 · 3 = 36。",
