"произведение из 6 цифр: 23 476 · 21 = 492 996; 19 031 · 51 = 970 581": "积是 6 位数：23 476 · 21 = 492 996；19 031 · 51 = 970 581",
"произведение из 6 цифр: 23 476 · 21 = 492 996; 19 031 · 51 = 970 581": "积是 6 位数：23 476 · 21 = 492 996；19 031 · 51 = 970 581",
"Остаток всегда меньше делителя. Из этих чисел меньше 245 только 244.": "余数总是比除数小。这些数里只有 244 比 245 小。",
"Из условия: брюк 180 шт., курток 120 шт. Какой вопрос задают первым?": "由条件：裤子 180 件，夹克 120 件。先问哪个问题？",
"При умножении чисел, оканчивающихся нулями, нули приписывают в конце.": "乘末尾有零的数时，把零添在末尾。",
"Сотни умножаем отдельно и записываем со сдвигом на два разряда влево.": "百位单独乘，写的时候向左空出两位。",
"Вспомни: сначала разность, потом значение на одну штуку, потом ответ.": "想一想：先求差，再求一件的值，最后得答案。",
"Чтобы найти время работы, надо объём разделить на производительность.": "要求工作时间，得用工作量除以工作效率。",
"Принтер печатает 5 листов в минуту. За 2 часа он напечатает 10 листов.": "打印机每分钟打印 5 张。2 小时它打印 10 张。",
"Расстояние равно скорости удаления, умноженной на время: S = v_уд · t.": "距离等于相背速度乘以时间：S = v相背 · t。",
"Одна тетрадь: 150 : 3 = 50 тенге. За 9 тетрадей: 50 · 9 = 450 (тенге).": "一本练习本：150 : 3 = 50 坚戈。9 本练习本：50 · 9 = 450（坚戈）。",
