"1 000 : 65 = 15 (ост. 25). Хватит на 15 билетов, останется 25 тенге.": "1 000 : 65 = 15 (余 25)。够买 15 张票, 还剩 25 坚戈。",
"7 ручек — 490 тг; 12 — ? Цена единицы: 490 : 7 = 70 тг; ответ 840 тг": "7 支笔 490 坚戈; 12 支 ? 单价: 490 : 7 = 70 坚戈; 答案 840 坚戈",
"За 1 час расстояние растёт на скорость удаления: 55 + 65 = 120 (км).": "1 小时距离增加一个远离速度: 55 + 65 = 120 (千米)。",
"Нули множителей при письменном умножении умножают, как обычные цифры.": "竖式乘法中, 因数末尾的零要像普通数字一样相乘。",
"Расход за 1 час одинаковый, а часов больше — значит, и литров больше.": "每小时用量相同, 小时数更多, 所以升数也更多。",
"Скорость сближения — сумма скоростей двух объектов, которые уже едут.": "靠近速度是已经在行驶的两个物体的速度之和。",
"2 · 3 = 6, значит, 15 · 6 = 90. Можно и так: 15 · 2 = 30, 30 · 3 = 90.": "2 · 3 = 6, 所以 15 · 6 = 90。也可以这样: 15 · 2 = 30, 30 · 3 = 90。",
"Как проверить, что за 5 ч — 40 л, а за 9 ч — 72 л (расход одинаковый)?": "怎样检验 5 小时 40 升, 9 小时 72 升 (每小时用量相同)?",
"Скорость удаления — сумма скоростей, поэтому она больше каждой из них.": "远离速度是速度之和, 所以它比每个速度都大。",
"Письменно умножать числа, оканчивающиеся нулями, и проверять результат": "会用竖式乘末尾有零的数, 并检验结果",
