"есть остаток: 86 213 : 82 = 1 051 (ост. 31); 5 659 : 54 = 104 (ост. 43)": "有余数: 86 213 : 82 = 1 051 (余 31); 5 659 : 54 = 104 (余 43)",
"Подбирая цифру частного, можно делить сотни делимого на сотни делителя.": "试商时, 可以用被除数的百位除以除数的百位。",
"Что дано в условии задачи на нахождение неизвестного по двум разностям?": "在由两个差求未知量的应用题中, 条件里给出了什么?",
"Совместная производительность находится вычитанием производительностей.": "合作的工作效率是用工作效率相减求出的。",
"произведение из 7 цифр: 6 000 · 500 = 3 000 000; 2 400 · 800 = 1 920 000": "积是 7 位数: 6 000 · 500 = 3 000 000; 2 400 · 800 = 1 920 000",
"произведение из 7 цифр: 6 000 · 500 = 3 000 000; 2 400 · 800 = 1 920 000": "积是 7 位数: 6 000 · 500 = 3 000 000; 2 400 · 800 = 1 920 000",
"частное двузначное: 1 206 : 34 = 35 (ост. 16); 2 759 : 69 = 39 (ост. 68)": "商是两位数: 1 206 : 34 = 35 (余 16); 2 759 : 69 = 39 (余 68)",
"частное двузначное: 1 206 : 34 = 35 (ост. 16); 2 759 : 69 = 39 (ост. 68)": "商是两位数: 1 206 : 34 = 35 (余 16); 2 759 : 69 = 39 (余 68)",
"Швея сшила 48 блузок за 3 дня. С какой производительностью она работала?": "女裁缝 3 天缝了 48 件上衣。她的工作效率是多少?",
"У комнат одинаковая ширина 4 м, длины 7 м и 5 м. Разность площадей 6 м².": "房间的宽度都是 4 米, 长度是 7 米和 5 米。面积的差是 6 平方米。",
"Отбрасываем по одному нулю: 54 810 : 9 = 6 090. Не забудь нуль в частном!": "各去掉一个零: 54 810 : 9 = 6 090。别忘了商里的零!",
"Отбрасываем по одному нулю: 54 810 : 9 = 6 090. Не забудь нуль в частном!": "各去掉一个零: 54 810 : 9 = 6 090。别忘了商里的零!",
"Совместная производительность равна сумме производительностей участников.": "合作的工作效率等于各人工作效率的和。",
"(x + 24) · 5 = 300, значит x + 24 = 300 : 5 = 60. Тогда x = 60 − 24 = 36.": "(x + 24) · 5 = 300, 所以 x + 24 = 300 : 5 = 60。那么 x = 60 − 24 = 36。",
"первое неполное произведение из 3 цифр: 412 · 12 = 4 944; 213 · 43 = 9 159": "第一个部分积是 3 位数: 412 · 12 = 4 944; 213 · 43 = 9 159",
"первое неполное произведение из 3 цифр: 412 · 12 = 4 944; 213 · 43 = 9 159": "第一个部分积是 3 位数: 412 · 12 = 4 944; 213 · 43 = 9 159",
