"из заданного расстояния вычесть начальное и разделить на скорость удаления": "用规定的距离减去起始距离, 再除以远离速度",
"Умножение на двузначное число состоит из умножения на единицы и на десятки.": "乘两位数包括乘个位和乘十位两部分。",
"Мастер: 12 · 6 = 72 дет. Ученик: 7 · 4 = 28 дет. Вместе: 72 + 28 = 100 дет.": "师傅: 12 · 6 = 72 个零件。徒弟: 7 · 4 = 28 个零件。一共: 72 + 28 = 100 个零件。",
"На каком расстоянии от посёлка Асета они встретились (12 км/ч, в пути 4 ч)?": "他们在离阿塞特的村子多远的地方相遇 (12 千米/时, 走了 4 小时)?",
"Два комбайнёра убрали поле: 2 дня и 4 дня с равной выработкой, всего 120 га": "两个联合收割机手收割田地: 2 天和 4 天, 每天收割量相同, 一共 120 公顷",
"частное трёхзначное: 72 567 : 87 = 834 (ост. 9); 63 694 : 78 = 816 (ост. 46)": "商是三位数: 72 567 : 87 = 834 (余 9); 63 694 : 78 = 816 (余 46)",
"частное трёхзначное: 72 567 : 87 = 834 (ост. 9); 63 694 : 78 = 816 (ост. 46)": "商是三位数: 72 567 : 87 = 834 (余 9); 63 694 : 78 = 816 (余 46)",
"Цену килограмма находят, деля общую стоимость на 3, если купили 3 кг и 5 кг.": "如果买了 3 千克和 5 千克, 求 1 千克的价钱, 要用总价除以 3。",
"Что надо сделать в первую очередь в задаче на неизвестное по двум разностям?": "在由两个差求未知量的应用题中, 首先要做什么?",
"Сначала умножаем числа без нулей, потом приписываем нули из обоих множителей.": "先乘没有零的数, 再把两个因数里的零都添在后面。",
"Сначала умножение: 150 · 40 = 6 000. Потом сложение: 12 000 + 6 000 = 18 000.": "先算乘法: 150 · 40 = 6 000。再算加法: 12 000 + 6 000 = 18 000。",
"Сначала умножение: 150 · 40 = 6 000. Потом сложение: 12 000 + 6 000 = 18 000.": "先算乘法: 150 · 40 = 6 000。再算加法: 12 000 + 6 000 = 18 000。",
"Сколько часов был в пути Асет до встречи с Ержаном (он выехал на 1 ч раньше)?": "阿塞特到和叶尔詹相遇走了几小时 (他比叶尔詹早出发 1 小时)?",
"Привет! Это Барсик. Сегодня делим круглые числа уголком. Нажимай на карточки.": "你好! 我是巴尔西克。今天我们用竖式除整百整十的数。点一点卡片吧。",
"Прикидка показала: 412 · 198 примерно равно 80 000. Какой ответ правдоподобен?": "估算表明: 412 · 198 大约等于 80 000。哪个答案是合理的?",
"Прикидка показала: 412 · 198 примерно равно 80 000. Какой ответ правдоподобен?": "估算表明: 412 · 198 大约等于 80 000。哪个答案是合理的?",
"Сначала разность количеств, потом значение на единицу, потом значение каждого.": "先求数量的差, 再求每一份的数值, 最后求各自的数值。",
"Второе действие отвечает на вопрос задачи. 8 · 9 = 72 (л) — расход за 9 часов.": "第二步回答题目的问题。8 · 9 = 72 (升) — 9 小时的用量。",
"частное больше 999: 59 516 : 25 = 2 380 (ост. 16); 74 205 : 36 = 2 061 (ост. 9)": "商大于 999: 59 516 : 25 = 2 380 (余 16); 74 205 : 36 = 2 061 (余 9)",
"частное больше 999: 59 516 : 25 = 2 380 (ост. 16); 74 205 : 36 = 2 061 (ост. 9)": "商大于 999: 59 516 : 25 = 2 380 (余 16); 74 205 : 36 = 2 061 (余 9)",
