"Работу находим умножением: A = v · t. Мастер делает 14 дет./ч и работает 6 ч: 14 · 6 = 84 дет.": "用乘法求工作量: A = v · t。师傅每小时做 14 个零件, 工作 6 小时: 14 · 6 = 84 个零件。",
"Типография в Алматы за 8 часов напечатала 640 листовок. Сколько листовок она печатает за 1 час?": "阿拉木图的印刷厂 8 小时印了 640 张传单。它 1 小时印多少张传单?",
"Умножать число на произведение и делить число на произведение, выбирая удобный порядок действий": "会用数乘积、用数除以积, 并选择方便的运算顺序",
"Хлебозавод в Шымкенте за 40 рабочих дней выпек 326 800 батонов. Сколько батонов выпекали в день?": "奇姆肯特的面包厂 40 个工作日烤了 326 800 个长面包。每天烤多少个长面包?",
"Хлебозавод в Шымкенте за 40 рабочих дней выпек 326 800 батонов. Сколько батонов выпекали в день?": "奇姆肯特的面包厂 40 个工作日烤了 326 800 个长面包。每天烤多少个长面包?",
"Один насос качает 40 вёдер воды в час, другой — 25. Сколько вёдер они накачают вместе за 4 часа?": "一台水泵每小时抽 40 桶水, 另一台抽 25 桶。它们一起 4 小时能抽多少桶?",
"Чтобы проверить деление с остатком, пользуемся формулой a = b · c + r. 25 · 19 + 8 = 483. Верно!": "检验有余数的除法, 用公式 a = b · c + r。25 · 19 + 8 = 483。正确!",
"Самолёт летит из Астаны в Алматы со скоростью 800 км/ч. Сколько километров он пролетит за 3 часа?": "飞机以 800 千米/时的速度从阿斯塔纳飞往阿拉木图。它 3 小时飞多少千米?",
"Пекарня должна выпечь 1 200 лепёшек, выпекая по 80 лепёшек в час. За сколько часов она справится?": "面包店要烤 1 200 个饼, 每小时烤 80 个饼。多少小时能烤完?",
"Пекарня должна выпечь 1 200 лепёшек, выпекая по 80 лепёшек в час. За сколько часов она справится?": "面包店要烤 1 200 个饼, 每小时烤 80 个饼。多少小时能烤完?",
