"Частное 207, потому что 318 · 207 = 65 826. Остаток: 65 890 − 65 826 = 64. Он меньше делителя 318.": "商是 207, 因为 318 · 207 = 65 826。余数: 65 890 − 65 826 = 64。它比除数 318 小。",
"Объём работы делим на совместную производительность: t = A : v совм. Заказ 90 дет.: 90 : 30 = 3 ч.": "用工作量除以合作的工作效率: t = A : v_合。订单 90 个零件: 90 : 30 = 3 小时。",
"Какой формулой находят расстояние между объектами, которые движутся в противоположных направлениях?": "用哪个公式求向相反方向运动的物体之间的距离?",
"1) 8 кг всего. 2) 300 тг — цена 1 кг. 3) 300 · 3 = 900 (тг) — яблоки. Проверка: 900 + 1 500 = 2 400.": "1) 一共 8 千克。2) 300 坚戈 — 1 千克的单价。3) 300 · 3 = 900 (坚戈) — 苹果。检验: 900 + 1 500 = 2 400。",
"1) 8 кг всего. 2) 300 тг — цена 1 кг. 3) 300 · 3 = 900 (тг) — яблоки. Проверка: 900 + 1 500 = 2 400.": "1) 一共 8 千克。2) 300 坚戈 — 1 千克的单价。3) 300 · 3 = 900 (坚戈) — 苹果。检验: 900 + 1 500 = 2 400。",
"Формулы — это верные равенства, которые связывают величины. Их три: A = v · t, v = A : t, t = A : v.": "公式是把各个量联系起来的正确等式。一共有三个: A = v · t, v = A : t, t = A : v。",
"Привет! Это Барсик. Сегодня решаем задачи, где объекты отдаляются друг от друга. Нажимай на карточки.": "你好! 我是巴尔西克。今天我们解物体彼此远离的应用题。点一点卡片吧。",
"Через сколько часов после выхода второго поезда они встретятся (60 км/ч и 40 км/ч, между ними 300 км)?": "第二列火车出发后过几小时他们相遇 (60 千米/时和 40 千米/时, 相距 300 千米)?",
"Делитель округляем до десятков: 78 — это почти 80. Пробуем цифру и умножаем на делитель: 8 · 78 = 624.": "把除数四舍五入到整十: 78 差不多是 80。试一个数字, 再乘除数: 8 · 78 = 624。",
"Два самосвала перевезли 120 т песка за одинаковое число рейсов, возя по 6 т и по 9 т. Рейсов было по 8.": "两辆自卸车运了 120 吨沙子, 趟数相同, 分别每趟运 6 吨和 9 吨。各跑了 8 趟。",
"Если выехали из разных мест, к расстоянию отдаления прибавляем начальное. 12 + (15 + 13) · 3 = 96 (км).": "如果从不同的地方出发, 要在远离的距离上加上起始距离。12 + (15 + 13) · 3 = 96 (千米)。",
"Поезда идут навстречу со скоростями 50 км/ч и 70 км/ч, между станциями 600 км. Они встретятся через 5 ч.": "火车相向而行, 速度是 50 千米/时和 70 千米/时, 两站之间相距 600 千米。它们 5 小时后相遇。",
"Второе неполное произведение получено умножением на 3 десятка. Его первую цифру записываем под десятками.": "第二个部分积是乘 3 个十得到的。它的第一个数字写在十位下面。",
"Если неполное делимое меньше делителя, в частном пишем 0 и сносим следующую цифру. 640 278 : 213 = 3 006.": "如果部分被除数小于除数, 就在商里写 0, 再落下下一个数字。640 278 : 213 = 3 006。",
"Если неполное делимое меньше делителя, в частном пишем 0 и сносим следующую цифру. 640 278 : 213 = 3 006.": "如果部分被除数小于除数, 就在商里写 0, 再落下下一个数字。640 278 : 213 = 3 006。",
