"В Караганде для зимней дороги заготовили 108 машин песка по 2 500 кг. Сколько килограммов песка заготовили?": "在卡拉干达, 为冬季道路备了 108 辆车的沙子, 每辆 2 500 千克。一共备了多少千克沙子?",
