"Сначала найдём, на сколько они должны отдалиться: 168 − 8 = 160 (км). Скорость удаления 40 км/ч. Время: 160 : 40 = 4 (ч).": "先求他们应该相距多远: 168 − 8 = 160 (千米)。远离速度是 40 千米/时。时间: 160 : 40 = 4 (小时)。",
