"Если объекты выехали из одного места, расстояние между ними равно (v₁ + v₂) · t. 3 ч при 60 км/ч и 40 км/ч: 100 · 3 = 300 км.": "如果物体从同一个地方出发, 它们之间的距离等于 (v₁ + v₂) · t。60 千米/时和 40 千米/时走 3 小时: 100 · 3 = 300 千米。",
