"Спрашивают про разное время, поэтому находим, сколько спиливают за 1 час.": "问的是不同的时间，所以先求 1 小时锯掉多少。",
"Они удаляются друг от друга. Это движение в противоположных направлениях.": "他们互相远离。这是向相反方向的运动。",
