"Скорость удаления: 800 + 900 = 1 700 (км/ч). Расстояние: 1 700 · 2 = 3 400 (км).": "远离速度：800 + 900 = 1 700（千米/时）。距离：1 700 · 2 = 3 400（千米）。",
