"Остаток 25 можно ещё разделить на 25. Остатки при делении на 25 — от 0 до 24.": "余数 25 还可以再除以 25。除以 25 的余数是从 0 到 24。",
"Сначала узнаём, что приходится на единицу, а потом отвечаем на вопрос задачи.": "先求出每一份是多少,然后回答应用题的问题。",
