"Урок 13. Умножение и деление на трёхзначное число: задачи, проверка, прикидка": "第 13 课。三位数的乘法和除法:应用题、检验、估算",
"Совместная производительность больше производительности каждого из участников.": "合作的工作效率比每个人单独的工作效率都大。",
"Скорость удаления: 270 : 3 = 90 (км/ч). Скорость второго: 90 − 40 = 50 (км/ч).": "相离速度:270 : 3 = 90 (千米/时)。第二个的速度:90 − 40 = 50 (千米/时)。",
"Первое неполное делимое 624. 624 : 78 = 8 (8 · 78 = 624, остаток 0). Частное 8.": "第一个部分被除数是 624。624 : 78 = 8 (8 · 78 = 624,余数 0)。商是 8。",
"Если за 1 час расходуется одно и то же, то чем больше часов, тем больше расход.": "如果每小时用量相同,那么小时数越多,用量越大。",
