"Неверно: нужно найти разность, потом значение на единицу, потом значение каждого.": "错误:应该先求差,再求一份的数值,然后求各自的数值。",
"Если за 9 тетрадей на 150 тенге больше, чем за 6, то одна тетрадь стоит 25 тенге.": "如果 9 本练习本比 6 本多花 150 坚戈,那么一本练习本 25 坚戈。",
"В задаче на противоположное движение расстояние можно найти только одним способом.": "在相背而行的应用题里,距离只能用一种方法求。",
"Первый поезд вышел на 2 ч раньше второго. Сначала он едет один: 60 · 2 = 120 (км).": "第一列火车比第二列早出发 2 小时。起初它自己走:60 · 2 = 120 (千米)。",
