"1) 15 + 13 = 28 (км/ч). 2) 28 · 3 = 84 (км) — они отдалились. 3) 84 + 12 = 96 (км).": "1) 15 + 13 = 28 (千米/时)。2) 28 · 3 = 84 (千米)是它们分开的距离。3) 84 + 12 = 96 (千米)。",
"Произведение, на которое делим, берём в скобки. 48 : (2 · 3) = 8, а 48 : 2 · 3 = 72.": "要除以的积要加括号。48 : (2 · 3) = 8,而 48 : 2 · 3 = 72。",
"За 9 дней пекарня в Астане выпекла 720 батонов. Сколько батонов она выпекает в день?": "阿斯塔纳的面包房 9 天烤了 720 个长面包。它一天烤多少个长面包?",
