"расход на одно изделие: 120 м : 60 изд. = 2 м на 1; 1 800 м : 300 костюмов = 6 м на 1": "每件产品的用量:120 米 : 60 件 = 每件 2 米;1 800 米 : 300 套衣服 = 每套 6 米",
