"Расстояние: S = S₀ + (v₁ + v₂) · t. От турбаз в 20 км, 8 и 6 км/ч, 3 ч: 20 + 14 · 3 = 62 (км).": "距离:S = S₀ + (v₁ + v₂) · t。两个旅游基地相距 20 千米,速度 8 和 6 千米/时,3 小时:20 + 14 · 3 = 62 (千米)。",
