"На ипподроме в Астане 44 280 зрителей сидят по рядам поровну. В каждом ряду 205 мест. Сколько рядов?": "阿斯塔纳赛马场的 44 280 名观众平均坐在各排。每排有 205 个座位。有多少排?",
"На ипподроме в Астане 44 280 зрителей сидят по рядам поровну. В каждом ряду 205 мест. Сколько рядов?": "阿斯塔纳赛马场的 44 280 名观众平均坐在各排。每排有 205 个座位。有多少排?",
