"Вместе работа делается быстрее. Заказ 480 пирожков: один печёт за 8 ч, второй за 24 ч, вместе за 6 ч — меньше 8.": "一起干活完成得更快。480 个馅饼的订单:一个人 8 小时烤完,另一个人 24 小时,一起 6 小时——比 8 小时少。",
