"За 18 дней мастерская в Туркестане сшила 2 340 тюбетеек. Какое выражение показывает, сколько тюбетеек шили за день?": "突厥斯坦的作坊 18 天缝了 2 340 顶小圆帽。哪个算式表示每天缝多少顶小圆帽?",
"Каждый объект прошёл свой путь за 6 ч. Сумма путей — это всё расстояние: 570 км. Второй способ: (50 + 45) · 6 = 570.": "每个物体 6 小时走完各自的路程。路程之和就是全部距离:570 千米。第二种方法:(50 + 45) · 6 = 570。",
"Берём цифры слева, пока число не станет не меньше делителя. 1 < 42, 17 < 42, 176 > 42. Первое неполное делимое — 176.": "从左边取数字,直到这个数不比除数小。1 < 42,17 < 42,176 > 42。第一个部分被除数是 176。",
