"500 человек, а в автобус помещается 45. 500 : 45 = 11 (ост. 5). Пять человек ещё остались, нужен ещё один автобус: 12.": "500 个人,一辆大巴能坐 45 人。500 : 45 = 11 (余 5)。还剩 5 个人,还需要一辆大巴:12 辆。",
"Из Тараза в противоположные стороны выехали две машины: 90 км/ч и 80 км/ч. Какое расстояние будет между ними через 2 ч?": "两辆车从塔拉兹向相反的方向驶出:90 千米/时和 80 千米/时。2 小时后它们之间相距多远?",
