"Например, «на 1 800 тг больше». Чтобы найти искомую величину, надо сначала узнать разность двух других известных величин.": "例如,“多 1 800 坚戈”。要求未知的量,先要求出另外两个已知量的差。",
"Например, «на 1 800 тг больше». Чтобы найти искомую величину, надо сначала узнать разность двух других известных величин.": "例如,“多 1 800 坚戈”。要求未知的量,先要求出另外两个已知量的差。",
"Берём цифры делимого слева, пока число не станет не меньше делителя. В 624 : 78 цифры 6 и 62 меньше 78, поэтому берём 624.": "从左边取被除数的数字,直到这个数不比除数小。在 624 : 78 中,数字 6 和 62 比 78 小,所以取 624。",
"Привет! Это Барсик. Сегодня делим на трёхзначное число, когда в частном есть нуль или остаётся остаток. Нажимай на карточки.": "你好!我是巴尔西克。今天我们学习除数是三位数的除法,商里有零或者有余数。点一点卡片吧。",
