"Объекты выехали из разных мест в противоположных направлениях. Как найти время, за которое между ними станет заданное расстояние?": "物体从不同的地方向相反的方向出发。怎样求它们之间相距指定距离所用的时间?",
"Выполнять письменное деление на двузначное число: находить первое неполное делимое, подбирать цифры частного и проверять результат": "学会用笔算做除数是两位数的除法:找第一个部分被除数,试商,并检验结果",
