"Нулевое неполное произведение (на десятки) не пишем, но место для него оставляем. Произведение на 3 сотни начинаем писать под сотнями.": "为零的部分积(十位的)不写,但要给它留出位置。乘以 3 个百的积要从百位下面开始写。",
"Первое неполное делимое 336. 336 : 66 = 5 (5 · 66 = 330, остаток 6). Сносим цифру: 66. 66 : 66 = 1 (1 · 66 = 66, остаток 0). Частное 51.": "第一个部分被除数是 336。336 : 66 = 5 (5 · 66 = 330,余数 6)。落下数字:66。66 : 66 = 1 (1 · 66 = 66,余数 0)。商是 51。",
