"Арман едет со скоростью 14 км/ч, Света — 12 км/ч. Они выехали навстречу друг другу и встретились через 2 ч. Какое расстояние между посёлками?": "阿尔曼的速度是 14 千米/时,斯韦塔的速度是 12 千米/时。他们相向出发,2 小时后相遇。两个村子之间的距离是多少?",
"Первое неполное произведение пишем под единицами, второе — под десятками, третье — под сотнями. Каждое следующее сдвигаем на один разряд влево.": "第一个部分积写在个位下面,第二个写在十位下面,第三个写在百位下面。每下一个都向左移一位。",
"Двое рабочих изготовили 56 деталей. Один работал 3 часа, другой — 4 часа, а производительность у них одинаковая. Сколько деталей изготовил второй?": "两名工人一共做了 56 个零件。一个工作了 3 小时,另一个工作了 4 小时,他们的工作效率相同。第二个人做了多少个零件?",
