"Если неполное делимое меньше делителя, в частном пишем 0 и сносим следующую цифру. Цифры частного: 3, 0, 0, 4. Ответ 3 004. Проверка: 3 004 · 125 = 375 500.": "如果部分被除数比除数小,就在商里写 0,再落下一位数字。商的数字:3,0,0,4。答案 3 004。检验:3 004 · 125 = 375 500。",
