"Школьники Павлодара собрали 6 000 тенге для приюта. Корм для одной собаки стоит 85 тенге. Сколько тенге останется после покупки корма для всех собак, которых можно накормить?": "巴甫洛达尔的学生为收容所募集了 6 000 坚戈。一条狗的狗粮 85 坚戈。给所有能喂饱的狗买完狗粮后,还剩多少坚戈?",
"Первое неполное делимое 48. 48 : 25 = 1 (1 · 25 = 25, остаток 23). Сносим цифру: 233. 233 : 25 = 9 (9 · 25 = 225, остаток 8). Получилось 19 (ост. 8). Проверка: 25 · 19 + 8 = 483.": "第一个部分被除数是 48。48 : 25 = 1 (1 · 25 = 25,余数 23)。落下数字:233。233 : 25 = 9 (9 · 25 = 225,余数 8)。得 19 (余 8)。检验:25 · 19 + 8 = 483。",
